sys_script_include.script:
var NeedItUtils = Class.create();
NeedItUtils.prototype = {
    initialize: function() {
		this.rightnow = new GlideDateTime();
		this.todayDate = this.rightnow.getDate();

    },
	isDatePast: function(strDate){
    // Create GlideDateTime objects for the passed in date

	var testdate = new GlideDateTime(strDate);

    // If the testdate is before rightnow, return true, else return false
	if (testdate.before(this.rightnow)) {
		return true;
		}
		else {
			return false;
			}
  },
  // Compares given date with today´s date without time specification
    isDateToday: function(inputDate){
		// Create GlideDateTime object for input date
		var dateToBeCompared = new GlideDateTime (inputDate);
		// Convert the DateTime into Date only
		if (this.todayDate.equals(dateToBeCompared.getDate())) {
			return true;
		}
		else {
			return false;
		}
	},

    type: 'NeedItUtils'
};
